})

// ── Usage ───────────────────────────────────────────────────────

const kit = solanaKit({
  cluster: 'devnet',
  programs: { escrow },
  plugins: [tokenPlugin()],
})

// Create an escrow
const maker = kit.payer
const escrowAddr = escrow.accounts.escrow.derive({ maker, escrowId: 1n })

await kit.execute(
  escrow.instructions.make({
    escrow: escrowAddr,
    maker,
    makerAta: kit.token.getAssociatedTokenAddress({ owner: maker, mint: mintA }),
    mintA: 'So11111111111111111111111111111111111111112', // SOL
    mintB: 'EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v', // USDC
    escrowId: 1n,
    makerAmount: lamports('1'),    // 1 SOL
    takerAmount: 100_000_000n,      // 100 USDC
  })
)

// Fetch the escrow account
const escrowAccount = await kit.fetchAccount(escrow.accounts.escrow, escrowAddr)
console.log(`Offering ${escrowAccount.makerAmount} for ${escrowAccount.takerAmount}`)

// Another user takes it
const taker = await kit.loadSignerFromEnv('TAKER_KEYPAIR')
await kit.execute(
  escrow.instructions.take({
    escrow: escrowAddr,
    taker,
    // ... other accounts resolved from escrow state
  })
)
```

---

## What Ships in the Box

```
@solana-kit/sdk                       # Core: solanaKit(), defineProgram(), execute(), fetchAccount()
@solana-kit/sdk/programs/system       # Built-in client for System Program
@solana-kit/sdk/programs/token        # Built-in client for Token Program
@solana-kit/sdk/programs/associated-token  # Built-in client for ATA Program
@solana-kit/sdk/testing               # testKit() with LiteSVM
@solana-kit/sdk/types                 # u64, bool, pubKey, string, etc.
```

Optional companion (not required for library usage):
```
@solana-kit/cli                       # Optional CLI: generate Rust, deploy, etc.
```

---

## Library vs Framework Checklist

| Question | Answer |
|---|---|
| Do I need a CLI to use it? | **No.** CLI is optional, only for Rust generation + deploy |
| Do I need a special folder structure? | **No.** Put files wherever you want |
| Do I need a config file? | **No.** Pass config to `solanaKit()` directly |
| Do I need to run a build step before using it? | **No.** Everything works at runtime via imports |
| Can I use it in an existing project? | **Yes.** `npm install` and import |
| Does it take over my test runner? | **No.** Use any test runner with `testKit()` |
| Can I use just the parts I need? | **Yes.** Don't need program definition? Don't import it. Don't need testing? Don't import it. |
| Can I drop down to @solana/kit? | **Yes.** `kit.rpc` gives you full RPC access |
| Does it work in browser? | **Yes.** `solanaKit()` detects environment and adapts |
| Does it work in Node? | **Yes.** Same API |

