  PropertyAccessExpression: {
    pattern: 'obj.prop',
    rustTemplate: (obj, prop, isSigner) => {
      if (isSigner) return obj + '.key()';
      return obj + '.' + toSnakeCase(prop);
    },
    note: 'Signer accounts use .key() to get Pubkey. Account fields use snake_case.',
  },

  // Binary: =
  FirstAssignment: {
    pattern: 'left = right',
    rustTemplate: 'left = right;',
    note: 'Direct mapping. Types must match.',
  },

  // Binary: +=
  FirstCompoundAssignment: {
    patterns: ['+=', '-=', '*=', '/='],
    rustTemplate: 'left += right;',
    note: 'Maps directly to Rust compound assignment.',
  },

  // Binary: ===
  EqualsEqualsEqualsToken: {
    pattern: 'left === right',
    rustTemplate: 'left == right',
    note: 'TS === maps to Rust ==. For Pubkey comparison, both sides need to be Pubkey type.',
  },

  // Binary: >, <, >=, <=
