// ============================================================
// THE ULTIMATE TEST: Transpile a real AMM swap instruction
// This is the most complex common Solana program pattern
// ============================================================

const ammSwapLogic = `
({ pool, trader, poolAccountA, poolAccountB, traderAccountA, traderAccountB, tokenProgram }, { amountIn, minimumAmountOut }) => {
  // Read current reserves
  const reserveIn = poolAccountA.amount;
  const reserveOut = poolAccountB.amount;

  // Calculate fee
  const fee = (amountIn * pool.feeBps) / 10000n;

  // Calculate output using constant product formula: x * y = k
  const netIn = amountIn - fee;
  const amountOut = (netIn * reserveOut) / (reserveIn + netIn);

  // Slippage protection
  require(amountOut >= minimumAmountOut);

  // Update pool state
  pool.totalTrades += 1n;
  pool.totalVolume += amountIn;

  // Transfer tokens from trader to pool
  tokenProgram.transfer({
    from: traderAccountA,
    to: poolAccountA,
    authority: trader,
    amount: amountIn,
  });

  // Transfer tokens from pool to trader (PDA-signed)
  tokenProgram.transfer({
    from: poolAccountB,
    to: traderAccountB,
    authority: pool,
    amount: amountOut,
  });

  // Emit trade event
  emit({ name: "SwapExecuted", amountIn, amountOut, fee });
}
`;

// Parse it
