let arrowFn = null;
ts.forEachChild(sf, node => {
  if (ts.isVariableStatement(node)) {
    const decl = node.declarationList.declarations[0];
    if (decl.initializer) arrowFn = decl.initializer;
  }
});

// === Count unique AST node types ===
const nodeKinds = new Set();
function visit(node) {
  const kind = ts.SyntaxKind[node.kind];
  // Only count meaningful nodes (not trivia, not semicolons)
  const meaningful = [
    'Identifier', 'PropertyAccessExpression', 'BinaryExpression',
    'CallExpression', 'ObjectLiteralExpression', 'PropertyAssignment',
    'Block', 'ExpressionStatement', 'VariableStatement',
    'VariableDeclarationList', 'VariableDeclaration',
    'IfStatement', 'ForOfStatement', 'ForStatement',
    'FirstAssignment', 'FirstCompoundAssignment',
    'EqualsEqualsEqualsToken', 'GreaterThanEqualsToken',
    'GreaterThanToken', 'LessThanToken', 'PlusToken', 'MinusToken',
    'AsteriskToken', 'SlashToken', 'PercentToken',
    'BigIntLiteral', 'TrueKeyword', 'FalseKeyword',
    'StringLiteral', 'NumericLiteral', 'PrefixUnaryExpression',
    'ParenthesizedExpression', 'ArrayLiteralExpression',
    'ElementAccessExpression', 'ObjectBindingPattern',
    'BindingElement', 'ReturnStatement', 'DeleteExpression',
    'TemplateExpression', 'TaggedTemplateExpression',
    'ArrowFunction', 'FunctionExpression',
  ];
  if (meaningful.includes(kind)) {
    nodeKinds.add(kind);
  }
  ts.forEachChild(node, visit);
}
