// ============================================================
// WHAT IS TRULY IMPOSSIBLE?
// Operations that CANNOT be transpiled from TS to Rust
// ============================================================

const impossibleCases = [
  {
    category: "Dynamic Memory Layout",
    example: "Rust's Box<Vec<u8>> or manual memory management",
    why: "Solana programs use BPF alloc, not heap. Dynamic allocation is limited. TS has no concept of this.",
    verdict: "IRRELEVANT — Anchor handles this. Developers never touch memory layout.",
  },
  {
    category: "Zero-Copy Account Deserialization",
    example: "#[account(zero_copy)] for large accounts (>10KB)",
    why: "Zero-copy maps account data directly to structs with unsafe pointer casts. Can't express in TS.",
    verdict: "ESCAPE HATCH — Rare. Most programs use normal Anchor accounts. Zero-copy is for orderbooks, state compression.",
  },
  {
    category: "Instruction Introspection",
    example: "sol_get_processed_sibling_instruction — reading other instructions in the same transaction",
    why: "Used by Jito bundles, tip payments. Extremely niche.",
    verdict: "ESCAPE HATCH — <1% of programs need this.",
  },
  {
    category: "Custom Syscall Usage",
    example: "sol_log_64, sol_get_stack_height, AltBn128 syscall",
    why: "Very low-level. Not something developers should write directly.",
    verdict: "ESCAPE HATCH — Wrapped in helper functions if needed.",
  },
  {
    category: "State Compression / Merkle Trees",
    example: "Using Solana's concurrent merkle tree for compressed NFTs",
    why: "Complex crypto + custom account layout. Metaplex has its own SDK for this.",
    verdict: "OUT OF SCOPE — This is a specialized library problem, not a transpiler problem.",
  },
  {
    category: "Concurrent Operations",
    example: "RwLock, concurrent state updates across accounts",
    why: "Solana handles parallelism at the runtime level, not the program level. Programs are single-threaded.",
    verdict: "IRRELEVANT — Solana programs are inherently single-threaded per instruction.",
  },
  {
    category: "Arbitrary CPI to Unknown Programs",
    example: "Calling any program at runtime with dynamic instruction data (e.g., multisig executor)",
    why: "The program being called isn't known at compile time. No type info available.",
    verdict: "ESCAPE HATCH — Provide raw invoke() wrapper. Developer writes Rust for this.",
  },
  {
    category: "Token-2022 Extensions",
    example: "Confidential transfers, CPI guard, permanent delegate",
    why: "Each extension has unique instruction formats, accounts, and data layouts.",
    verdict: "DEFERRABLE — Provide typed CPI templates for common Token-2022 ops (transfer_checked, etc.). Extensions come later.",
  },
];

