const ts = require('typescript');
const fs = require('fs');

// ============================================================
// FULL VERIFICATION: Parse every instruction's logic function
// from the AMM program and verify all AST nodes are transpilable
// ============================================================

const source = fs.readFileSync('amm-program.ts', 'utf8');
const sf = ts.createSourceFile('amm.ts', source, ts.ScriptTarget.Latest, true);

// Extract all logic functions from the source
const logicFunctions = [];

function findLogicFunctions(node) {
  // Look for: logic: ({ ... }, { ... }) => { ... }
  if (ts.isPropertyAssignment(node) && 
      ts.isIdentifier(node.name) && 
      node.name.text === 'logic') {

    const initializer = node.initializer;
    if (ts.isArrowFunction(initializer)) {
      // Get the instruction name from parent context
      let instrName = 'unknown';
      let parent = node.parent;
      while (parent) {
        if (ts.isPropertyAssignment(parent) && ts.isIdentifier(parent.name)) {
          instrName = parent.name.text;
          break;
        }
        parent = parent.parent;
      }

      logicFunctions.push({
        name: instrName,
        node: initializer,
        start: initializer.getStart(),
        end: initializer.getEnd(),
      });
    }
  }
  ts.forEachChild(node, findLogicFunctions);
}

findLogicFunctions(sf);

console.log(`Found ${logicFunctions.length} logic functions to verify\n`);

// Our transpiler's supported AST node types
const SUPPORTED_NODES = new Set([
  // Statements
  'ExpressionStatement', 'VariableStatement', 'VariableDeclarationList',
  'VariableDeclaration', 'IfStatement', 'Block', 'ReturnStatement',
  'ForOfStatement', 'ForStatement',

  // Expressions
  'PropertyAccessExpression', 'BinaryExpression', 'CallExpression',
  'ObjectLiteralExpression', 'PropertyAssignment',
  'PrefixUnaryExpression', 'ParenthesizedExpression',
  'ConditionalExpression',    // ternary — we should support this
  'ElementAccessExpression',
  'TaggedTemplateExpression',
  'AsExpression',
  'NonNullExpression',
  'ArrayLiteralExpression',

  // Identifiers & Literals
  'Identifier', 'BigIntLiteral', 'StringLiteral', 'NumericLiteral',
  'TrueKeyword', 'FalseKeyword', 'NullKeyword', 'UndefinedKeyword',
  'NoSubstitutionTemplateLiteral',

  // Bindings
  'ObjectBindingPattern', 'ArrayBindingPattern', 'BindingElement',

  // Operators
  'FirstAssignment', 'FirstCompoundAssignment', 'FirstBinaryOperator',
  'EqualsEqualsEqualsToken', 'ExclamationEqualsEqualsToken',
  'GreaterThanToken', 'LessThanToken', 'GreaterThanEqualsToken', 'LessThanEqualsToken',
  'PlusToken', 'MinusToken', 'AsteriskToken', 'SlashToken', 'PercentToken',
  'AmpersandAmpersandToken', 'BarBarToken',
  'QuestionToken', 'ColonToken',
  'CommaToken', 'DotToken', 'SemicolonToken',
  'EqualsGreaterThanToken',  // =>
  'OpenParenToken', 'CloseParenToken',
  'OpenBraceToken', 'CloseBraceToken',
  'OpenBracketToken', 'CloseBracketToken',
]);

const UNSUPPORTED_NODES = new Set([
  'TryStatement', 'CatchClause', 'ThrowStatement',  // try/catch
  'SwitchStatement', 'CaseClause', 'DefaultClause',  // switch/case
  'WhileStatement', 'DoStatement',                   // while/do
  'ForInStatement',                                  // for..in
  'NewExpression',                                   // new X()
  'DeleteExpression', 'TypeOfExpression', 'VoidExpression',
  'YieldExpression', 'AwaitExpression',              // async/generators
  'ClassExpression', 'ClassDeclaration',              // classes
  'FunctionExpression',                               // function expressions
  'TemplateExpression',                               // template literals with interpolation
  'SpreadElement', 'SpreadAssignment',
  'RegularExpressionLiteral',
  'EnumDeclaration', 'InterfaceDeclaration', 'TypeAliasDeclaration',
  'ImportDeclaration', 'ExportDeclaration',
]);

// Process each logic function
let totalErrors = 0;
let totalWarnings = 0;

logicFunctions.forEach((fn, idx) => {
  const nodeKinds = new Map();
  const unknownNodes = [];
  const unsupportedOps = [];
  const identifiers = new Set();
  const localVars = new Set();
  const cpiCalls = [];

  function analyze(node, depth) {
    const kind = ts.SyntaxKind[node.kind];

    // Track node kinds
    nodeKinds.set(kind, (nodeKinds.get(kind) || 0) + 1);

    // Check for unsupported constructs
    if (UNSUPPORTED_NODES.has(kind)) {
      const line = sf.getLineAndCharacterOfPosition(node.getStart()).line + 1;
      unsupportedOps.push({ kind, line });
    }

    // Track identifiers
    if (ts.isIdentifier(node)) {
      identifiers.add(node.text);
    }

    // Track local variable declarations
    if (ts.isVariableDeclaration(node) && ts.isIdentifier(node.name)) {
      localVars.add(node.name.text);
    }

    // Track CPI calls
    if (ts.isCallExpression(node) && ts.isPropertyAccessExpression(node.expression)) {
      const obj = node.expression.expression;
      const method = node.expression.name.text;
      if (ts.isIdentifier(obj)) {
        const objName = obj.text;
        if (['token', 'system', 'ata', 'token2022'].includes(objName)) {
          cpiCalls.push(`${objName}.${method}()`);
        }
      }
    }

    ts.forEachChild(node, child => analyze(child, depth + 1));
  }

  analyze(fn.node.body, 0);

  // Determine status
  const hasErrors = unsupportedOps.length > 0;
  const status = hasErrors ? '❌ ERRORS' : '✅ OK';

  // Get line number
  const startLine = sf.getLineAndCharacterOfPosition(fn.start).line + 1;
  const endLine = sf.getLineAndCharacterOfPosition(fn.end).line + 1;

  console.log(`┌─────────────────────────────────────────────────────┐`);
  console.log(`│ ${idx + 1}. ${fn.name.padEnd(47)} │`);
  console.log(`│    Lines ${startLine}-${endLine}  (${endLine - startLine + 1} lines)`.padEnd(57) + '│');
  console.log(`│    Status: ${status}`.padEnd(57) + '│');
  console.log(`└─────────────────────────────────────────────────────┘`);

  // Show details
  if (cpiCalls.length > 0) {
    console.log(`  CPI calls: ${[...new Set(cpiCalls)].join(', ')}`);
  }

  if (localVars.size > 0) {
    console.log(`  Local vars: ${[...localVars].join(', ')}`);
  }

  // Show AST node summary
  const meaningful = [...nodeKinds.entries()]
    .filter(([k]) => !k.includes('Token') || k.includes('First') || 
      ['EqualsEqualsEqualsToken', 'GreaterThanEqualsToken', 'GreaterThanToken', 
       'LessThanToken', 'AsteriskToken', 'SlashToken', 'PlusToken', 'MinusToken',
       'PercentToken', 'AmpersandAmpersandToken'].includes(k))
    .sort((a, b) => b[1] - a[1])
    .slice(0, 15);

  console.log(`  Top AST nodes: ${meaningful.map(([k, v]) => `${k}(${v})`).join(', ')}`);

  if (unsupportedOps.length > 0) {
    console.log(`  ❌ UNSUPPORTED:`);
    unsupportedOps.forEach(u => {
      console.log(`     Line ${u.line}: ${u.kind}`);
    });
    totalErrors += unsupportedOps.length;
  }

  // Check for any node types we haven't classified
  const unclassified = [...nodeKinds.keys()].filter(
    k => !SUPPORTED_NODES.has(k) && !UNSUPPORTED_NODES.has(k) && 
    !k.endsWith('Token') && k !== 'SourceFile' && k !== 'EndOfFileToken' &&
    k !== 'SyntaxList' && k !== 'FirstStatement' && k !== 'VariableStatement' &&
    k !== 'ObjectBindingPattern' && k !== 'BindingElement'
  );

  if (unclassified.length > 0) {
    console.log(`  ⚠️  UNCLASSIFIED nodes: ${unclassified.join(', ')}`);
    totalWarnings += unclassified.length;
  }

  console.log('');
});

// ═══════════════════════════════════════════
// Verify the specific transpilation for the hardest instruction (swapAForB)
// ═══════════════════════════════════════════
console.log('═══════════════════════════════════════════════════════════');
console.log('DEEP DIVE: swapAForB — Transpilation verification');
console.log('═══════════════════════════════════════════════════════════');
console.log('');

const swapFn = logicFunctions.find(f => f.name === 'swapAForB');
if (swapFn) {
  const body = swapFn.node.body;
  const stmts = body.statements;

  console.log(`Statements in swapAForB: ${stmts.length}`);
  console.log('');

  stmts.forEach((stmt, i) => {
    const text = stmt.getText().substring(0, 80).replace(/\n/g, ' ').trim();
    const kind = ts.SyntaxKind[stmt.kind];

    let transpileStatus = '✅';
    let rustOutput = '';

    // Analyze each statement type
    if (ts.isExpressionStatement(stmt)) {
      const expr = stmt.expression;

      if (ts.isCallExpression(expr) && ts.isIdentifier(expr.expression) && 
          expr.expression.text === 'require') {
        transpileStatus = '✅';
        rustOutput = 'require!(...);';
      } else if (ts.isCallExpression(expr) && ts.isPropertyAccessExpression(expr.expression)) {
        const method = expr.expression.name.text;
        if (['transfer', 'mintTo', 'burn'].includes(method)) {
          transpileStatus = '✅';
          rustOutput = `token::${method}(...)`;
        }
      } else if (ts.isBinaryExpression(expr)) {
        const op = expr.operatorToken.getText();
        if (op === '+=' || op === '-=') {
          transpileStatus = '✅';
          rustOutput = 'field += value;';
        } else if (op === '=') {
          transpileStatus = '✅';
          rustOutput = 'field = value;';
        }
      }
    } else if (ts.isVariableStatement(stmt)) {
      transpileStatus = '✅';
      rustOutput = 'let name = expr;';
    } else if (ts.isIfStatement(stmt)) {
      transpileStatus = '✅';
      rustOutput = 'if cond { ... }';
    }

    console.log(`  ${i + 1}. [${transpileStatus}] ${kind}`);
    console.log(`     TS:   ${text}`);
    console.log(`     Rust: ${rustOutput}`);
    console.log('');
  });
}

