  tokenAMint: pubkey,
  tokenBMint: pubkey,
  feeBps: u64,
  lpSupply: u64,
  isActive: bool,
  bump: u8,
}).seeds('pool', '{tokenAMint}', '{tokenBMint}')

// Instructions reference accounts — like tRPC procedures
