// ============================================================
// TYPE SAFETY TEST: Can TypeScript infer types from our API?
// ============================================================
// Let's test whether different syntax approaches give us real type inference

// ── Simulating our type system ──

// Field types (runtime values that carry type info)
type SolType<T> = { __sol_type: T }

const u64: SolType<bigint> = { __sol_type: {} as bigint }
const u8: SolType<number> = { __sol_type: {} as number }
const bool: SolType<boolean> = { __sol_type: {} as boolean }
const pubkey: SolType<string> = { __sol_type: {} as string }

// Account definition result
type SolAccount<T extends Record<string, any>> = {
  __fields: T
  // ... plus runtime methods
}

// Infer the TypeScript type from an account definition
type InferAccount<T> = {
  [K in keyof T]: T[K] extends SolType<infer V> ? V : never
}

// ── Test: Can we infer account types? ──

const Config = {
  admin: pubkey,
  totalPools: u64,
  feeBps: u64,
  bump: u8,
} as const

type ConfigType = InferAccount<typeof Config>
// Should be: { admin: string; totalPools: bigint; feeBps: bigint; bump: number }

// Verify:
const _configTest: ConfigType = {
  admin: "xxx",
  totalPools: 1n,
  feeBps: 30n,
  bump: 1,
}

// ── Test: Can we type the logic function? ──

// Approach: The instruction definition receives typed accounts
type InstructionDef<
  TAccounts extends Record<string, any>,
  TArgs extends Record<string, SolType<any>>
> = {
  accounts: TAccounts
  args: TArgs
  run: (
    accounts: { [K in keyof TAccounts]: InferAccount<TAccounts[K]> },
    args: InferAccount<TArgs>
  ) => void
}

// ── The cleanest approach I can think of ──

// What if accounts are defined as Zod-like schemas,
// and the instruction's `run` function gets FULLY TYPED params?

interface AccountBuilder<T extends Record<string, SolType<any>>> {
  fields: T
  seeds: (...seeds: string[]) => AccountBuilder<T>
  // Chain methods for PDA, space, etc.
}

