ts.forEachChild(sf, () => {});

const diag = sf.parseDiagnostics || [];
if (diag.length > 0) {
  diag.forEach(d => console.log('Parse error:', d.messageText));
} else {
  console.log('✅ Parses cleanly');
}

// Count nesting depth at key points
function maxDepth(node, depth = 0) {
  let max = depth;
  ts.forEachChild(node, child => {
    max = Math.max(max, maxDepth(child, depth + 1));
  });
  return max;
}

console.log('Max AST depth:', maxDepth(sf));

// Check: does the 'run' function have typed params?
// Look for the pattern: run: ({ ... }, { ... }) => { ... }
let runFunctions = 0;
function findRun(node) {
