// ============================================================
// PROOF OF CONCEPT: End-to-End Type Safety
//
// Two questions to solve:
// 1. Can require(expr, 'ErrorName') be type-safe — autocomplete
//    from a predefined error registry, compile error if invalid?
// 2. Can p.tokenAccount('fieldName') be type-safe — autocomplete
//    from the account's pubkey fields, compile error if wrong?
//
// Approach: Use TypeScript 5.0 `const` type parameters +
//           branded helper types that carry metadata.
// ============================================================

// ── The core type machinery ──

// 1. Account definition carries field names as a type union
type AccountFields<T> = {
  [K in keyof T]: T[K] extends typeof pubkey ? K : never
}[keyof T]

// Simulate our type primitives
declare const u64: unique symbol
declare const u8: unique symbol
declare const bool_: unique symbol
declare const pubkey: unique symbol

type SolU64 = typeof u64
type SolU8 = typeof u8
type SolBool = typeof bool_
type SolPubkey = typeof pubkey

// 2. Account type that captures field names
interface SolAccount<TName extends string, TFields extends Record<string, any>> {
  name: TName
  fields: TFields
  // Type-level access to pubkey field names
  __pubkeyFields: {
    [K in keyof TFields as TFields[K] extends SolPubkey ? K : never]: K
  }
}

// 3. account() returns a typed object
function account<TName extends string, TFields extends Record<string, any>>(
  name: TName,
  fields: TFields
): SolAccount<TName, TFields> {
  return { name, fields, __pubkeyFields: {} as any }
}

// 4. tokenAccount() takes a field name from the parent account
// This is the KEY: the type parameter constrains the string literal
declare function tokenAccount<
  TAccount extends SolAccount<any, any>,
  TFieldName extends {
    [K in keyof TAccount['fields'] as TAccount['fields'][K] extends SolPubkey ? K : never]: K
  }[keyof TAccount['fields'] & string]
>(account: TAccount, field: TFieldName): TokenAccountRef<TFieldName>

interface TokenAccountRef<TField extends string> {
  field: TField
  mut(): TokenAccountRef<TField>
}

// 5. Error registry — type-safe error names
type ErrorRegistry<T extends Record<string, string>> = {
  [K in keyof T]: K
} & { __registry: T }

function defineErrors<const T extends Record<string, string>>(errors: T): ErrorRegistry<T> {
  return errors as any
}

// 6. require() that accepts only registered error names
declare function require<
  TErrors extends Record<string, string>,
  TErrorName extends keyof TErrors & string
>(
  condition: boolean,
  error: TErrorName
): void

// Also support require without error (just boolean)
declare function require(condition: boolean): void


// ══════════════════════════════════════════
// USAGE: Let's test the type safety
// ══════════════════════════════════════════

// Define an account
