  tokenBMint: pubkey,
  tokenAReserve: pubkey,
  tokenBReserve: pubkey,
  lpMint: pubkey,
  lpSupply: u64,
  feeBps: u64,
  isActive: bool_,
  admin: pubkey,
  bump: u8,
})

// Define errors
const errors = defineErrors({
  Unauthorized: 'Caller is not authorized',
  PoolDoesNotExist: 'Pool does not exist',
  SlippageExceeded: 'Output below minimum',
  InvalidAmount: 'Amount must be positive',
  InvalidFeeBps: 'Fee exceeds maximum',
  InsufficientLiquidity: 'Not enough liquidity',
})

// ═══ TEST 1: tokenAccount field name type safety ═══

// ✅ Should work: 'tokenAMint' is a pubkey field
const ta1 = tokenAccount(Pool, 'tokenAMint')

// ✅ Should work: 'tokenBMint' is a pubkey field  
const ta2 = tokenAccount(Pool, 'tokenBMint')

